"""
Gemma 4 Developer Agent — scorer-faithful local evaluation on Kaggle GPU L4 x4.

Mirrors the scoring stack as documented in HARNESS_README / the organizers' Getting Started notebook:
  - vLLM 0.19.1 from the official wheelhouse, gemma-4-31b-it-qat-w4a16-ct, tensor_parallel_size=4,
    gpu_memory_utilization=0.80, max_model_len=32768, gemma4 tool/reasoning parsers, enable_thinking default,
    multi-LoRA (max_loras=8, max_lora_rank=128) -> any adapters/ in the submission are served per agent.
  - official swegemma Evaluator, subprocess sandbox, tasks run ONE AT A TIME under the submission's eval_config.yaml.
  - agent sandbox made "offline" (dead proxy for everything except localhost), like network_mode=none.
Then runs trace_analyzer.py (if uploaded) and packages everything.

Notebook setup:
  - Accelerator: GPU L4 x4.
  - Inputs: competition data · dataset `gemma-4-developer-agent-wheelhouse` (owner: metric) ·
            Model google/gemma-4 -> gemma-4-31b-it-qat-w4a16-ct.
  - Upload this script + trace_analyzer.py. Optional: attach your own submission folder as a dataset and set
    SUBMISSION_DIR below (default = our baseline, identical to submission_baseline_v1.zip).
  - Internet: ON only if the preinstalled torch is not 2.10.0 (the script tells you); the agent stays offline anyway.
  - Save Version -> Save & Run All (Commit). Session cap ~12 h; tasks are scheduled in chunks until the budget ends.
Outputs (/kaggle/working): run.log · official_l4.tgz (traces, patches, logs, task_results, analysis/) · submission.zip
"""

import asyncio
import glob
import json
import os
import pathlib
import random
import re
import shutil
import subprocess
import sys
import time

CFG = {
    "SUBMISSION_DIR": None,      # None -> build the submission from VARIANT below
    "VARIANT": "v2_sed",      # "baseline" (0.00 LB) | "v2_sed" (no read_file; 0.08 LB) | "v2b_budget80" (v2, 80 calls) | "v3_verify" (v2 + verify plan) | "v4_pipeline" (localizer->fixer, 80 calls) | "v5_graph" (v4 + code-map skill) | "v6_trace" (relationship-first localizer, budgeted, richer handoff)
    "task_ids": None,            # None -> all 129, shuffled (stratified order) so a partial run is representative
    "seed": 0,
    "chunk_size": 8,
    "session_budget_h": 11.0,    # stop scheduling new chunks after this
    "est_task_min": 5.5,         # 4.5 min agent budget + setup/verification
    "results": None,             # None -> "official_l4_<VARIANT>" (+ "_dev" when DEVSET is on)
    "DEVSET": False,             # True -> evaluate on the renamed dev set (attach the dataset made by build_devset.py)
}
W = pathlib.Path("/kaggle/working")
TARGET = "gemma-4-31b-it-qat-w4a16-ct"
LOG = open(W / "run.log", "a", buffering=1)
T0 = time.time()


def log(*a):
    s = time.strftime("%H:%M:%S ") + " ".join(str(x) for x in a)
    print(s, flush=True)
    LOG.write(s + "\n")


def sh(cmd, timeout=None, check=False):
    log("$", cmd[:220])
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout)
    out = ((r.stdout or "")[-1500:] + ("\n" + r.stderr[-1500:] if (r.stderr or "").strip() else "")).strip()
    if out:
        log(out)
    if check and r.returncode != 0:
        raise SystemExit(f"FAILED rc={r.returncode}: {cmd[:120]}")
    return r


def first(pattern):
    hits = sorted(glob.glob(pattern, recursive=True))
    return hits[0] if hits else None


# ------------------------------------------------------------------ 0. hardware + inputs
sh("nvidia-smi --query-gpu=name,memory.total --format=csv,noheader; nproc; free -g | head -2; df -h /tmp | tail -1")
ngpu = int(subprocess.run("nvidia-smi -L | wc -l", shell=True, capture_output=True, text=True).stdout.strip() or 0)
if ngpu < 4:
    raise SystemExit("Need GPU L4 x4 (Settings -> Accelerator).")
_all_tasks = sorted(glob.glob("/kaggle/input/**/tasks.jsonl", recursive=True))
_comp = [p for p in _all_tasks if (pathlib.Path(p).parent / "graphs").is_dir()]
tasks_path = (_comp or _all_tasks or [None])[0]
assert tasks_path, "competition data not attached"
DATA = pathlib.Path(tasks_path).parent
SNAPS = DATA / "snapshots"
if CFG["DEVSET"]:
    _dev = [p for p in _all_tasks if (pathlib.Path(p).parent / "devset_report.json").exists()]
    assert _dev, "DEVSET=True but no dev set dataset attached (needs tasks.jsonl + snapshots/ + devset_report.json)"
    tasks_path = _dev[0]
    SNAPS = pathlib.Path(tasks_path).parent / "snapshots"
    log("DEV SET:", tasks_path)
whl = first("/kaggle/input/**/swegemma-*.whl")
assert whl, "attach dataset 'gemma-4-developer-agent-wheelhouse' (owner: metric)"
WH = pathlib.Path(whl).parent
def is_w4a16(cfg_path):
    if "w4a16" in cfg_path.lower():
        return True
    try:
        c = json.load(open(cfg_path))
        q = c.get("quantization_config") or c.get("text_config", {}).get("quantization_config") or {}
        return "31b" in cfg_path.lower() and "compressed" in str(q.get("quant_method", "")).lower()
    except Exception:  # noqa: BLE001
        return False


all_cfgs = glob.glob("/kaggle/input/**/config.json", recursive=True)
cfg_json = [p for p in all_cfgs if is_w4a16(p)]
if not cfg_json:
    log("config.json files found under /kaggle/input:", all_cfgs or "NONE")
    sh("ls /kaggle/input; ls /kaggle/input/* | head -40")
    raise SystemExit("Model not found. Add Input -> Models -> 'gemma-4' (Google) -> variation "
                     "'gemma-4-31b-it-qat-w4a16-ct' (framework 'Other' / 'Transformers'), then rerun.")
MODEL_PATH = str(pathlib.Path(sorted(cfg_json)[0]).parent)
log("DATA =", DATA, "| WHEELHOUSE =", WH, "| MODEL =", MODEL_PATH)

# ------------------------------------------------------------------ 1. environment exactly like the scorer
for k, v in {"LITELLM_LOCAL_MODEL_COST_MAP": "True", "TRANSFORMERS_NO_TF": "1", "VLLM_WORKER_MULTIPROC_METHOD": "spawn",
             "VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS": "1", "VLLM_ENGINE_READY_TIMEOUT_S": "1200",
             "VLLM_NO_USAGE_STATS": "1", "OTEL_SDK_DISABLED": "true",
             "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True"}.items():
    os.environ[k] = v
tv = subprocess.run([sys.executable, "-c", "import torch; print(torch.__version__)"],
                    capture_output=True, text=True).stdout.strip()
log("preinstalled torch:", tv or "none")
if not tv.startswith("2.10.0"):
    r = sh(f"{sys.executable} -m pip install -q torch==2.10.0 torchvision==0.25.0 torchaudio==2.10.0 "
           "--index-url https://download.pytorch.org/whl/cu128", timeout=3600)
    if r.returncode != 0:
        raise SystemExit("torch 2.10.0 is required by vLLM 0.19.1 and is not preinstalled: turn Internet ON and rerun.")
for pth in glob.glob("/usr/local/lib/python*/*-packages/*cutlass*.pth"):
    try:
        os.unlink(pth)
    except OSError:
        pass
stage = pathlib.Path("/tmp/wheelhouse")
stage.mkdir(exist_ok=True)
for w in WH.glob("*.whl"):
    if "cutlass" in w.name.lower():
        continue
    name = w.name.replace("cu128", "+cu128") if ("cu128" in w.name and "+" not in w.name) else w.name
    if not (stage / name).exists():
        os.symlink(w, stage / name)
sh(f"{sys.executable} -m pip install -q --no-deps --force-reinstall {' '.join(sorted(str(w) for w in stage.glob('*.whl')))}",
   timeout=3600, check=True)
sh(f"{sys.executable} -c 'import torch, vllm, swegemma, google.adk; "
   "print(\"torch\", torch.__version__, \"vllm\", vllm.__version__, \"adk\", google.adk.__version__)'", check=True)

# local-env fix: 32 fastapi tasks failed verification on missing test-only deps (inline_snapshot, dirty_equals).
# The subprocess sandbox venv sees host site-packages (_host_env.pth), so install them on the host, no-deps.
dep_whl = first("/kaggle/input/**/inline_snapshot-*.whl")
if dep_whl:  # offline: wheels attached as a Kaggle dataset (L4 sessions have no Internet)
    dd = pathlib.Path(dep_whl).parent
    wl = " ".join(str(p) for p in dd.glob("*.whl") if re.match(r"(inline_snapshot|dirty_equals|asttokens|executing)-", p.name))
    r = sh(f"{sys.executable} -m pip install -q --no-index --no-deps {wl}", timeout=600)
else:
    r = sh(f"{sys.executable} -m pip install -q --no-deps inline-snapshot dirty-equals asttokens executing", timeout=600)
sh(f"{sys.executable} -c 'import inline_snapshot, dirty_equals; print(\"test deps OK\")'")
if r.returncode != 0:
    log("WARNING: could not install inline-snapshot/dirty-equals (Internet off?) -> ~32 fastapi tasks will be unverifiable")

V3_BLOCK = """## Mandatory Budget Plan (follow it exactly)
- Calls 1-20: locate and read the relevant code (`grep -n`, `sed -n 'START,ENDp' path`). Do not re-read lines you already saw.
- By call 25 at the latest: make your edit with `edit_file`, even if you are not fully certain.
- Then verify ONCE: find the existing test file for the code you changed (`grep -rln "<function_or_class_name>" tests | head -3`)
  and run only it: `python -m pytest <that_test_file> -x -q 2>&1 | tail -20`.
- If the failure is caused by your change, fix it and rerun that same test once. Ignore failures unrelated to your change.
- Then call `submit_patch`. Keep scratch scripts in /tmp, never in /workspace."""

# ------------------------------------------------------------------ 2. submission under test
V4_FILES = json.loads('{"eval_config.yaml": "evaluation:\\n  timeout_seconds: 180\\n  max_tool_calls: 80\\n  max_time_minutes: 4.5\\n  max_turns: 160\\n", "agent.yaml": "name: swe_pipeline\\nagent_class: SequentialAgent\\ndescription: Two-stage issue resolver - localizer writes a diagnosis brief, fixer edits, verifies and submits.\\nsub_agents:\\n  - config_path: sub_agents/localizer.yaml\\n  - config_path: sub_agents/fixer.yaml\\n", "sub_agents/localizer.yaml": "name: localizer_agent\\ndescription: Finds the exact code responsible for the issue and writes a structured diagnosis. Never edits files.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/localizer.md\\ntools:\\n  - run_command\\n  - search_similar_code\\n  - get_code_neighbors\\n  - get_code_subgraph\\n  - get_status\\noutput_key: diagnosis\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n", "sub_agents/fixer.yaml": "name: fixer_agent\\ndescription: Applies and verifies the fix described in the diagnosis, then submits the patch.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/fixer.md\\ninclude_contents: none\\ntools:\\n  - run_command\\n  - edit_file\\n  - write_file\\n  - get_status\\n  - submit_patch\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n", "configs/sampling.yaml": "temperature: 0.2\\ntop_p: 0.95\\ntop_k: 40\\nmax_output_tokens: 8192\\nthinking_config:\\n  include_thoughts: false\\n", "prompts/fixer.md": "You are the FIXER in a two-stage bug-fixing team working in the repository at /workspace. The LOCALIZER has already investigated. Implement the fix, verify it, and submit.\\n\\n## Issue\\n{problem_description}\\n\\n## Localizer\'s diagnosis\\n{diagnosis?}\\n\\n## Workflow (follow in order)\\n1. Read the target code: `sed -n \'START,ENDp\' FILE` around the LINES in the diagnosis (at most ~80 lines). If the diagnosis is empty or clearly wrong, locate the code yourself with `grep -rn`.\\n2. Optional but recommended: write a tiny reproduction script to /tmp/repro.py that should fail before the fix, and run it with `python /tmp/repro.py`.\\n3. Apply the minimal fix with `edit_file`. Use a short, unique `old_string` copied exactly from the file. If an edit fails because of quotes or escaping, retry with a smaller `old_string` that avoids quote characters.\\n4. Verify ONCE: run only the TEST_FILE from the diagnosis (or the repro script): `python -m pytest TEST_FILE -x -q 2>&1 | tail -20`.\\n5. If the failure is caused by your change, fix it and rerun once. Ignore failures unrelated to your change.\\n6. Call `submit_patch`, then reply with a one-line summary.\\n\\n## Rules\\n- The environment is offline; all dependencies are installed. Never run pip install.\\n- Never modify, create or delete test files, conftest.py or pytest.ini. Change source code only.\\n- Never run the full test suite (bare `pytest`); always pass a specific test file.\\n- Keep scratch files in /tmp, never in /workspace.\\n- Always finish with `submit_patch`.\\n", "prompts/localizer.md": "You are the LOCALIZER in a two-stage bug-fixing team. Your only job: find the exact code that must change to resolve the issue, and hand a precise diagnosis to the FIXER. You must NOT modify any file.\\n\\n## How to search (read-only)\\n- Extract identifiers from the issue: function/class names, error messages, option names, file paths.\\n- Use `run_command` with `grep -rn \\"PATTERN\\" --include=*.py .` to find definitions and usages; exclude tests unless the issue is about tests.\\n- Read code with `sed -n \'START,ENDp\' path` (at most ~80 lines per read). Never re-read lines you have already seen.\\n- `get_code_neighbors(node)` shows callers/callees of a symbol (use a short symbol name like `solve_dependencies`). Use it once you have a candidate function, to check who calls it and what it calls. `search_similar_code` takes a symbol name, not a sentence.\\n- Find the most relevant existing test file: `grep -rln \\"SYMBOL\\" tests | head -5`.\\n- Budget: use at most ~25 tool calls. Stop searching as soon as you are confident.\\n\\n## Your final answer (plain text, no tool call after it), exactly this template:\\nFILE: <path relative to repo root>\\nLINES: <start>-<end>\\nFUNCTION: <function or class name>\\nROOT_CAUSE: <1-3 sentences: what the code does now vs what the issue requires>\\nPROPOSED_CHANGE: <concrete description of the minimal edit, including the exact current line(s) to change>\\nOTHER_LOCATIONS: <other places that need the same change, or \\"none\\">\\nTEST_FILE: <existing test file to run, or \\"none found\\">\\nCONFIDENCE: <high|medium|low>\\n"}')
V5_FILES = json.loads('{"agent.yaml": "name: swe_pipeline\\nagent_class: SequentialAgent\\ndescription: Two-stage issue resolver - localizer writes a diagnosis brief, fixer edits, verifies and submits.\\nsub_agents:\\n  - config_path: sub_agents/localizer.yaml\\n  - config_path: sub_agents/fixer.yaml\\n", "configs/sampling.yaml": "temperature: 0.2\\ntop_p: 0.95\\ntop_k: 40\\nmax_output_tokens: 8192\\nthinking_config:\\n  include_thoughts: false\\n", "eval_config.yaml": "evaluation:\\n  timeout_seconds: 180\\n  max_tool_calls: 80\\n  max_time_minutes: 4.5\\n  max_turns: 160\\n", "prompts/fixer.md": "You are the FIXER in a two-stage bug-fixing team working in the repository at /workspace. The LOCALIZER has already investigated. Implement the fix, verify it, and submit.\\n\\n## Issue\\n{problem_description}\\n\\n## Localizer\'s diagnosis\\n{diagnosis?}\\n\\n## Workflow (follow in order)\\n1. Read the target code: `sed -n \'START,ENDp\' FILE` around the LINES in the diagnosis (at most ~80 lines). If the diagnosis is empty or clearly wrong, locate the code yourself with `grep -rn`.\\n2. Optional but recommended: write a tiny reproduction script to /tmp/repro.py that should fail before the fix, and run it with `python /tmp/repro.py`.\\n3. Apply the minimal fix with `edit_file`. Use a short, unique `old_string` copied exactly from the file. If an edit fails because of quotes or escaping, retry with a smaller `old_string` that avoids quote characters.\\n4. Verify ONCE: run only the TEST_FILE from the diagnosis (or the repro script): `python -m pytest TEST_FILE -x -q 2>&1 | tail -20`.\\n5. If the failure is caused by your change, fix it and rerun once. Ignore failures unrelated to your change.\\n6. Call `submit_patch`, then reply with a one-line summary.\\n\\n## Rules\\n- The environment is offline; all dependencies are installed. Never run pip install.\\n- Never modify, create or delete test files, conftest.py or pytest.ini. Change source code only.\\n- Never run the full test suite (bare `pytest`); always pass a specific test file.\\n- Keep scratch files in /tmp, never in /workspace.\\n- Always finish with `submit_patch`.\\n", "prompts/localizer.md": "You are the LOCALIZER in a two-stage bug-fixing team. Your only job: find the exact code that must change to resolve the issue, and hand a precise diagnosis to the FIXER. You must NOT modify any file.\\n\\n## How to search (read-only)\\n- Extract identifiers from the issue: function/class names, error messages, option names, file paths.\\n- Use `run_command` with `grep -rn \\"PATTERN\\" --include=*.py .` to find definitions and usages; exclude tests unless the issue is about tests.\\n- Read code with `sed -n \'START,ENDp\' path` (at most ~80 lines per read). Never re-read lines you have already seen.\\n- STRUCTURE FIRST: once you have a candidate symbol, use the `code-map` skill instead of long grep chains:\\n  - `run_skill_script(skill_name=\\"code-map\\", file_path=\\"scripts/code_map.py\\", args=[\\"find\\", \\"NAME\\"])` gives the definition\'s file, line range and its exact qualified name.\\n  - `args=[\\"callers\\", \\"NAME\\"]` lists every call site with its enclosing function. `args=[\\"callees\\", \\"NAME\\"]` lists what it calls. `args=[\\"outline\\", \\"path/to/file.py\\"]` maps one file.\\n  - NAME can be bare (`solve_dependencies`) or `Class.method`.\\n- Graph tools need the EXACT qualified name that `find` prints, e.g. `fastapi.dependencies.utils.solve_dependencies`. They return nothing for bare names or sentences.\\n  - `get_code_neighbors(node=QUALIFIED_NAME)` returns callers and callees from the pre-built graph.\\n  - `search_similar_code(query=QUALIFIED_NAME)` returns code similar to that symbol. Use it to fill OTHER_LOCATIONS (sibling implementations that need the same fix).\\n  - Never pass a sentence or keywords to `search_similar_code`.\\n- Find the most relevant existing test file: `grep -rln \\"SYMBOL\\" tests | head -5`.\\n- Budget: use at most ~25 tool calls. Stop searching as soon as you are confident.\\n\\n## Your final answer (plain text, no tool call after it), exactly this template:\\nFILE: <path relative to repo root>\\nLINES: <start>-<end>\\nFUNCTION: <function or class name>\\nROOT_CAUSE: <1-3 sentences: what the code does now vs what the issue requires>\\nPROPOSED_CHANGE: <concrete description of the minimal edit, including the exact current line(s) to change>\\nOTHER_LOCATIONS: <other places that need the same change, or \\"none\\">\\nTEST_FILE: <existing test file to run, or \\"none found\\">\\nCONFIDENCE: <high|medium|low>\\n", "skills/code-map/SKILL.md": "---\\nname: code-map\\ndescription: Structural code lookup with Python ast. Find where a symbol is defined (with its exact graph node name), who calls it, what it calls, and a file outline. Works with bare names like solve_dependencies.\\n---\\n# code-map\\n\\nRun with `run_skill_script(skill_name=\\"code-map\\", file_path=\\"scripts/code_map.py\\", args=[COMMAND, NAME])`.\\n`args` is a list of strings.\\n\\n| Command | args example | Returns |\\n|---|---|---|\\n| find | `[\\"find\\", \\"solve_dependencies\\"]` | qualified node name, `file:start-end`, signature |\\n| callers | `[\\"callers\\", \\"solve_dependencies\\"]` | every call site: `file:line`, enclosing function, source line |\\n| callees | `[\\"callees\\", \\"solve_dependencies\\"]` | names called inside that function |\\n| outline | `[\\"outline\\", \\"fastapi/routing.py\\"]` | classes/functions of one file with line ranges |\\n\\n- Add `\\"--tests\\"` to include test files; add `\\"--limit\\", \\"50\\"` for more rows.\\n- NAME can be bare (`get_dependant`), `Class.method`, or a dotted path.\\n- The qualified name printed by `find` (e.g. `fastapi.dependencies.utils.solve_dependencies`) is the exact `node` to pass to `get_code_neighbors` and `search_similar_code`.\\n", "skills/code-map/scripts/code_map.py": "\\"\\"\\"code-map: structural lookup over the repository using Python\'s ast (stdlib only, no graph files needed).\\n\\nCommands (first positional argument):\\n  find NAME      definitions whose name matches NAME (bare `solve_dependencies`, `Class.method`, or a dotted path)\\n                 -> qualified graph name, file:line-range, signature\\n  callers NAME   call sites of NAME -> file:line, enclosing function, the source line\\n  callees NAME   names called inside the definition of NAME\\n  outline PATH   classes/functions of one file with line ranges\\n\\nOptions: --tests  include test files (excluded by default)   --limit N  max rows (default 25)\\nThe qualified names printed (e.g. `fastapi.dependencies.utils.solve_dependencies`) are exactly the node names\\nthat get_code_neighbors / search_similar_code / get_code_subgraph accept.\\n\\"\\"\\"\\nimport ast\\nimport inspect\\nimport os\\nimport subprocess\\nimport sys\\n\\nSKIP_DIRS = {\\".git\\", \\".venv\\", \\"venv\\", \\"node_modules\\", \\"build\\", \\"dist\\", \\"__pycache__\\", \\".tox\\", \\".eggs\\", \\"site-packages\\", \\"docs\\", \\"docs_src\\"}\\nMAX_FILES = 4000\\n\\n\\ndef repo_root():\\n    for fr in inspect.stack():\\n        cwd = fr.frame.f_locals.get(\\"_orig_cwd\\")\\n        if isinstance(cwd, str) and os.path.isdir(cwd):\\n            return git_top(cwd)\\n    for cand in (os.environ.get(\\"CODE_MAP_ROOT\\"), \\"/workspace\\", os.environ.get(\\"PWD\\"), os.getcwd()):\\n        if cand and os.path.isdir(cand) and not cand.startswith((\\"/tmp/tmp\\", \\"/var/folders\\")):\\n            return git_top(cand)\\n    return os.getcwd()\\n\\n\\ndef git_top(path):\\n    try:\\n        out = subprocess.run([\\"git\\", \\"rev-parse\\", \\"--show-toplevel\\"], cwd=path, capture_output=True, text=True,\\n                             timeout=10)\\n        if out.returncode == 0 and out.stdout.strip():\\n            return out.stdout.strip()\\n    except Exception:  # noqa: BLE001\\n        pass\\n    return path\\n\\n\\ndef is_test(rel):\\n    parts = rel.replace(\\"\\\\\\\\\\", \\"/\\").split(\\"/\\")\\n    base = parts[-1]\\n    return any(p in (\\"tests\\", \\"test\\", \\"testing\\") for p in parts[:-1]) or base.startswith(\\"test_\\") or \\\\\\n        base.endswith(\\"_test.py\\") or base == \\"conftest.py\\"\\n\\n\\ndef iter_py(root, tests):\\n    n = 0\\n    for dp, dns, fns in os.walk(root):\\n        dns[:] = sorted(d for d in dns if d not in SKIP_DIRS and not d.startswith(\\".\\"))\\n        for fn in sorted(fns):\\n            if not fn.endswith(\\".py\\"):\\n                continue\\n            full = os.path.join(dp, fn)\\n            rel = os.path.relpath(full, root)\\n            if not tests and is_test(rel):\\n                continue\\n            n += 1\\n            if n > MAX_FILES:\\n                return\\n            yield full, rel\\n\\n\\ndef module_name(rel):\\n    mod = rel[:-3].replace(os.sep, \\".\\").replace(\\"/\\", \\".\\")\\n    if mod.endswith(\\".__init__\\"):\\n        mod = mod[: -len(\\".__init__\\")]\\n    for prefix in (\\"src.\\", \\"lib.\\"):\\n        if mod.startswith(prefix):\\n            mod = mod[len(prefix):]\\n    return mod\\n\\n\\ndef parse(full):\\n    try:\\n        with open(full, encoding=\\"utf-8\\", errors=\\"replace\\") as f:\\n            src = f.read()\\n        return ast.parse(src), src.splitlines()\\n    except Exception:  # noqa: BLE001\\n        return None, []\\n\\n\\ndef defs(tree, mod):\\n    \\"\\"\\"Yield (qualname_without_module, node) for every class/function, with nesting.\\"\\"\\"\\n    stack = [(tree, \\"\\")]\\n    while stack:\\n        node, prefix = stack.pop()\\n        for ch in ast.iter_child_nodes(node):\\n            if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\\n                q = f\\"{prefix}.{ch.name}\\" if prefix else ch.name\\n                yield q, ch\\n                stack.append((ch, q))\\n            elif not isinstance(ch, (ast.expr,)):\\n                stack.append((ch, prefix))\\n\\n\\ndef matches(query, mod, q):\\n    full = f\\"{mod}.{q}\\"\\n    return full == query or full.endswith(\\".\\" + query) or q == query or q.split(\\".\\")[-1] == query\\n\\n\\ndef signature(node, lines):\\n    line = lines[node.lineno - 1].strip() if node.lineno - 1 < len(lines) else \\"\\"\\n    return line[:160]\\n\\n\\ndef call_name(call):\\n    f = call.func\\n    if isinstance(f, ast.Name):\\n        return f.id\\n    if isinstance(f, ast.Attribute):\\n        return f.attr\\n    return None\\n\\n\\ndef cmd_find(root, query, tests, limit):\\n    rows = []\\n    for full, rel in iter_py(root, tests):\\n        tree, lines = parse(full)\\n        if tree is None:\\n            continue\\n        mod = module_name(rel)\\n        for q, node in defs(tree, mod):\\n            if matches(query, mod, q):\\n                kind = \\"class\\" if isinstance(node, ast.ClassDef) else \\"def\\"\\n                rows.append(f\\"{mod}.{q}  [{kind}]  {rel}:{node.lineno}-{getattr(node, \'end_lineno\', node.lineno)}\\"\\n                            f\\"  | {signature(node, lines)}\\")\\n    if not rows:\\n        print(f\\"no definition named {query!r}. Try a shorter name, or grep -rn \\\\\\"{query.split(\'.\')[-1]}\\\\\\" .\\")\\n    for r in rows[:limit]:\\n        print(r)\\n    if len(rows) > limit:\\n        print(f\\"... {len(rows) - limit} more\\")\\n\\n\\ndef enclosing_map(tree):\\n    spans = []\\n    for q, node in defs(tree, \\"\\"):\\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\\n            spans.append((node.lineno, getattr(node, \\"end_lineno\\", node.lineno), q))\\n    return spans\\n\\n\\ndef enclosing(spans, lineno):\\n    best = None\\n    for s, e, q in spans:\\n        if s <= lineno <= e and (best is None or s >= best[0]):\\n            best = (s, e, q)\\n    return best[2] if best else \\"<module>\\"\\n\\n\\ndef cmd_callers(root, query, tests, limit):\\n    target = query.split(\\".\\")[-1]\\n    rows = []\\n    for full, rel in iter_py(root, tests):\\n        tree, lines = parse(full)\\n        if tree is None:\\n            continue\\n        spans = None\\n        mod = module_name(rel)\\n        for node in ast.walk(tree):\\n            if isinstance(node, ast.Call) and call_name(node) == target:\\n                spans = spans if spans is not None else enclosing_map(tree)\\n                src = lines[node.lineno - 1].strip() if node.lineno - 1 < len(lines) else \\"\\"\\n                rows.append(f\\"{rel}:{node.lineno}  in {mod}.{enclosing(spans, node.lineno)}  | {src[:140]}\\")\\n    if not rows:\\n        print(f\\"no call sites of {target!r} found (it may be passed as a value, used via getattr, or only in tests;\\"\\n              f\\" try --tests or grep).\\")\\n    for r in rows[:limit]:\\n        print(r)\\n    if len(rows) > limit:\\n        print(f\\"... {len(rows) - limit} more\\")\\n\\n\\ndef cmd_callees(root, query, tests, limit):\\n    for full, rel in iter_py(root, tests):\\n        tree, lines = parse(full)\\n        if tree is None:\\n            continue\\n        mod = module_name(rel)\\n        for q, node in defs(tree, mod):\\n            if matches(query, mod, q) and not isinstance(node, ast.ClassDef):\\n                seen = []\\n                for ch in ast.walk(node):\\n                    if isinstance(ch, ast.Call):\\n                        nm = call_name(ch)\\n                        if nm and nm not in seen:\\n                            seen.append(nm)\\n                print(f\\"{mod}.{q}  {rel}:{node.lineno}  calls: {\', \'.join(seen[:limit * 2]) or \'(nothing)\'}\\")\\n                return\\n    print(f\\"no function named {query!r}\\")\\n\\n\\ndef cmd_outline(root, path, limit):\\n    full = path if os.path.isabs(path) else os.path.join(root, path)\\n    tree, lines = parse(full)\\n    if tree is None:\\n        print(f\\"cannot parse {path}\\")\\n        return\\n    mod = module_name(os.path.relpath(full, root))\\n    out = []\\n    for q, node in defs(tree, mod):\\n        depth = q.count(\\".\\")\\n        out.append((node.lineno, f\\"{\'  \' * depth}{q}  {node.lineno}-{getattr(node, \'end_lineno\', node.lineno)}\\"))\\n    print(f\\"module {mod}\\")\\n    for _, s in sorted(out)[: limit * 4]:\\n        print(s)\\n\\n\\ndef main(argv):\\n    args = [a for a in argv if a != \\"--\\"]\\n    tests = \\"--tests\\" in args\\n    limit = 25\\n    if \\"--limit\\" in args:\\n        i = args.index(\\"--limit\\")\\n        try:\\n            limit = int(args[i + 1])\\n        except (IndexError, ValueError):\\n            pass\\n        del args[i:i + 2]\\n    args = [a for a in args if a != \\"--tests\\"]\\n    if len(args) < 2 or args[0] not in (\\"find\\", \\"callers\\", \\"callees\\", \\"outline\\"):\\n        print(__doc__)\\n        return\\n    cmd, query = args[0], args[1].strip().strip(\\"`\'\\\\\\"()\\")\\n    root = repo_root()\\n    if cmd == \\"find\\":\\n        cmd_find(root, query, tests, limit)\\n    elif cmd == \\"callers\\":\\n        cmd_callers(root, query, tests, limit)\\n    elif cmd == \\"callees\\":\\n        cmd_callees(root, query, tests, limit)\\n    else:\\n        cmd_outline(root, query, limit)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main(sys.argv[1:])\\n", "sub_agents/fixer.yaml": "name: fixer_agent\\ndescription: Applies and verifies the fix described in the diagnosis, then submits the patch.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/fixer.md\\ninclude_contents: none\\ntools:\\n  - run_command\\n  - edit_file\\n  - write_file\\n  - get_status\\n  - submit_patch\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n", "sub_agents/localizer.yaml": "name: localizer_agent\\ndescription: Finds the exact code responsible for the issue and writes a structured diagnosis. Never edits files.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/localizer.md\\ntools:\\n  - run_command\\n  - search_similar_code\\n  - get_code_neighbors\\n  - get_code_subgraph\\n  - get_status\\nskills:\\n  - skills/code-map\\noutput_key: diagnosis\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n"}')
V6_FILES = json.loads('{"agent.yaml": "name: swe_pipeline\\nagent_class: SequentialAgent\\ndescription: Two-stage issue resolver - localizer writes a diagnosis brief, fixer edits, verifies and submits.\\nsub_agents:\\n  - config_path: sub_agents/localizer.yaml\\n  - config_path: sub_agents/fixer.yaml\\n", "configs/sampling.yaml": "temperature: 0.2\\ntop_p: 0.95\\ntop_k: 40\\nmax_output_tokens: 8192\\nthinking_config:\\n  include_thoughts: false\\n", "eval_config.yaml": "evaluation:\\n  timeout_seconds: 180\\n  max_tool_calls: 64\\n  max_time_minutes: 4.5\\n  max_turns: 130\\n", "prompts/fixer.md": "You are the FIXER in a two-stage bug-fixing team working in the repository at /workspace. The LOCALIZER has already traced the code and written a brief. Implement the fix, verify it, and submit. You have about 25 tool calls.\\n\\n## Issue\\n{problem_description}\\n\\n## Localizer\'s brief\\n{diagnosis?}\\n\\n## Workflow (in order)\\n1. Confirm: `sed -n \'START,ENDp\' FILE` for the brief\'s LINES, widened by about 10 lines. Do this once.\\n   - If the brief is empty or the code does not match CURRENT_CODE, locate it yourself with `grep -rn` (at most 5 calls).\\n2. Edit: apply the FIX with `edit_file`. Copy `old_string` from the file as shown by `sed`, without line numbers.\\n   - Keep `old_string` to 1-6 consecutive lines that are unique in the file.\\n   - Never put docstrings or triple-quoted strings in `old_string`.\\n   - Make one small edit per call. Apply the same change to OTHER_LOCATIONS if they apply.\\n3. If `edit_file` fails with \\"mandatory input parameters are not present\\", the call was garbled by quotes or backslashes.\\n   - Retry once with `old_string` = ONE distinctive line containing no quotes or backslashes.\\n   - If that fails too, rewrite the lines by number with a python heredoc:\\n     `python3 - <<\'PY\'` that reads FILE, replaces `lines[a:b]`, and writes it back.\\n4. Verify once: run the brief\'s TEST_COMMAND with `2>&1 | tail -25` appended. If it is \\"none found\\", write a 5-10 line `/tmp/check.py` that exercises the issue\'s example, and run it.\\n5. If the failure is caused by your change, fix it and rerun once. Ignore failures unrelated to your change, such as pre-existing failures or missing optional modules.\\n6. Call `submit_patch`, then reply with a one-line summary.\\n\\n## Rules\\n- The environment is offline and all dependencies are installed. Never run pip install.\\n- Never modify, create or delete test files, conftest.py or pytest.ini. Change source code only.\\n- Never run the full test suite (bare `pytest`). Always pass a specific test file.\\n- Keep scratch files in /tmp, never in /workspace.\\n- Always finish with `submit_patch`, even if verification is incomplete.\\n", "prompts/localizer.md": "You are the LOCALIZER in a two-stage bug-fixing team. Find the exact code that must change to resolve the issue, understand how it is reached, and hand the FIXER a brief that lets them edit immediately. You never modify files.\\n\\n## Your only tool: the `code-map` skill\\nCall it as `run_skill_script(skill_name=\\"code-map\\", file_path=\\"scripts/code_map.py\\", args=[...])`. Do not call `list_skills` or `load_skill`: everything you need is here.\\n- `[\\"search\\", \\"REGEX\\"]`: text search; every hit shows its enclosing function.\\n- `[\\"show\\", \\"path/file.py\\", \\"START\\", \\"END\\"]`: read lines (max 100 per call).\\n- `[\\"find\\", \\"NAME\\"]`: definition, file, line range.\\n- `[\\"trace\\", \\"NAME\\"]`: definition, callers, callees, overrides and tests in ONE call.\\n- `[\\"callers\\", \\"NAME\\"]`: who calls it, 2 levels up.\\n- `[\\"callees\\", \\"NAME\\"]`: what it calls, with definitions.\\n- `[\\"path\\", \\"PUBLIC_API\\", \\"INTERNAL\\"]`: the call chain between two functions.\\n- `[\\"similar\\", \\"NAME\\"]`: other places that may need the same change.\\n- `[\\"tests\\", \\"NAME\\"]`: tests that reference it, with the run command.\\n- `[\\"outline\\", \\"path/file.py\\"]`: map of one file.\\n- NAME can be bare (`solve_dependencies`), `Class.method`, or dotted.\\n\\nYou have 22 calls. After that the tool refuses and you must answer.\\n\\n## Method: follow the relationships, not just the text\\n1. ANCHOR (1-3 calls). Pull the concrete anchors out of the issue: the public API the user called, error messages, parameter or option names. `search` for them, or `find` a named symbol.\\n2. TRACE (2-6 calls). `trace` the best candidate. Then move along the relationships:\\n   - From the public entry point the issue uses, go down (`callees`, `path ENTRY CANDIDATE`) to where the wrong value is produced.\\n   - From a low-level helper, go up (`callers`) to check which caller passes the wrong data.\\n   - The bug is where behaviour first diverges from what the issue expects. It is often one hop away from where the symptom appears.\\n3. READ (2-5 calls). `show` the exact lines of the function you believe is wrong. Read its callee or caller too if the logic depends on it.\\n4. SCOPE (1-2 calls). `similar` on the function: list siblings that need the same change (for example the same method in sibling classes). Use `tests` to get the test file and run command.\\n5. Stop as soon as you can fill the brief. Never repeat a call you already made.\\n\\n## Final answer: plain text, no tool call after it, exactly these fields\\nSUMMARY: <one line: what is wrong>\\nFILE: <path relative to repo root>\\nLINES: <start>-<end>\\nFUNCTION: <qualified name>\\nCURRENT_CODE:\\n<the exact current lines that must change, copied verbatim from `show` output WITHOUT the line numbers, at most 20 lines>\\nCALL_CONTEXT: <entry point -> ... -> FUNCTION chain from trace/path/callers, plus any callee that matters>\\nROOT_CAUSE: <1-3 sentences: what the code does now vs what the issue requires>\\nFIX: <1-3 concrete bullet steps: which line(s) change and the new code or logic>\\nOTHER_LOCATIONS: <qualified names and file:line that need the same change, or \\"none\\">\\nTEST_COMMAND: <e.g. python -m pytest tests/test_x.py -x -q, or \\"none found\\">\\nCONFIDENCE: <high|medium|low> because <the evidence: what trace/path/show established>\\n", "skills/code-map/SKILL.md": "---\\nname: code-map\\ndescription: Read-only, relationship-first code navigation for Python repos - search with enclosing function, show lines, definitions, callers, callees, call paths, similar code and related tests.\\n---\\n# code-map\\n\\nCall: `run_skill_script(skill_name=\\"code-map\\", file_path=\\"scripts/code_map.py\\", args=[...])`. `args` is a list of strings.\\n\\n| Goal | args |\\n|---|---|\\n| Search text/regex; every hit shows its enclosing function | `[\\"search\\", \\"PATTERN\\"]` |\\n| Read lines (max 100) | `[\\"show\\", \\"path/file.py\\", \\"START\\", \\"END\\"]` |\\n| Where is X defined | `[\\"find\\", \\"NAME\\"]` |\\n| Everything around X in one call: definition, callers, callees, overrides, tests | `[\\"trace\\", \\"NAME\\"]` |\\n| Who calls X (2 levels up) | `[\\"callers\\", \\"NAME\\"]` |\\n| What X calls | `[\\"callees\\", \\"NAME\\"]` |\\n| How public API A reaches internal B | `[\\"path\\", \\"A\\", \\"B\\"]` |\\n| Other places that may need the same fix | `[\\"similar\\", \\"NAME\\"]` |\\n| Which tests cover X | `[\\"tests\\", \\"NAME\\"]` |\\n| Map of one file | `[\\"outline\\", \\"path/file.py\\"]` |\\n\\nNAME can be bare (`solve_dependencies`), `Class.method`, or a dotted path. Add `\\"--tests\\"` to include test files.\\n", "skills/code-map/scripts/code_map.py": "\\"\\"\\"code-map v2: read-only, relationship-first navigation of a Python repository (stdlib only).\\n\\nUsage: args=[COMMAND, ...]\\n  search PATTERN        regex search; each hit shows file:line and the ENCLOSING function/class\\n  show FILE START END   print lines START..END (max 100) with line numbers and the enclosing symbol\\n  find NAME             definitions of NAME (bare, Class.method or dotted) -> qualified name, file:lines, signature\\n  trace NAME            one-shot relationship view: definition + callers + callees + overrides + tests\\n  callers NAME          who calls NAME, 2 levels up (call chains towards public entry points)\\n  callees NAME          what NAME calls, resolved to definitions with file:line\\n  path FROM TO          shortest call chain FROM -> ... -> TO (e.g. public API -> buggy helper)\\n  similar NAME          overrides / same-named methods / structurally similar functions (other places to fix)\\n  tests NAME            test files and test functions that reference NAME\\n  outline FILE          classes and functions of one file with line ranges\\n  status                calls used / remaining\\nOptions: --tests (include test files where relevant)\\n\\"\\"\\"\\nimport ast\\nimport collections\\nimport hashlib\\nimport inspect\\nimport json\\nimport os\\nimport pickle\\nimport re\\nimport subprocess\\nimport sys\\n\\nBUDGET = 22  # code-map calls allowed per task before the localizer must hand off\\nSKIP_DIRS = {\\".git\\", \\".venv\\", \\"venv\\", \\"env\\", \\"node_modules\\", \\"build\\", \\"dist\\", \\"__pycache__\\", \\".tox\\", \\".eggs\\",\\n             \\"site-packages\\", \\"docs\\", \\"docs_src\\", \\".mypy_cache\\", \\".pytest_cache\\"}\\nMAX_FILES = 6000\\nMAX_OUT = 3800\\nCOMMON = {\\"get\\", \\"set\\", \\"append\\", \\"extend\\", \\"update\\", \\"items\\", \\"keys\\", \\"values\\", \\"pop\\", \\"join\\", \\"split\\", \\"strip\\",\\n          \\"format\\", \\"replace\\", \\"startswith\\", \\"endswith\\", \\"isinstance\\", \\"len\\", \\"str\\", \\"int\\", \\"dict\\", \\"list\\", \\"tuple\\",\\n          \\"print\\", \\"super\\", \\"getattr\\", \\"setattr\\", \\"hasattr\\", \\"type\\", \\"range\\", \\"enumerate\\", \\"zip\\", \\"sorted\\", \\"min\\",\\n          \\"max\\", \\"any\\", \\"all\\", \\"map\\", \\"filter\\", \\"open\\", \\"repr\\", \\"bool\\", \\"float\\", \\"add\\", \\"copy\\", \\"write\\", \\"read\\",\\n          \\"lower\\", \\"upper\\", \\"encode\\", \\"decode\\", \\"match\\", \\"search\\", \\"sub\\", \\"insert\\", \\"remove\\", \\"clear\\", \\"close\\",\\n          \\"next\\", \\"iter\\", \\"id\\", \\"hash\\", \\"abs\\", \\"sum\\", \\"round\\", \\"issubclass\\", \\"callable\\", \\"vars\\", \\"object\\", \\"set\\"}\\n\\n_out = []\\n\\n\\ndef emit(s=\\"\\"):\\n    _out.append(str(s))\\n\\n\\ndef flush():\\n    text = \\"\\\\n\\".join(_out)\\n    if len(text) > MAX_OUT:\\n        text = text[:MAX_OUT] + \\"\\\\n... (truncated; narrow the query)\\"\\n    print(text)\\n\\n\\n# ---------------------------------------------------------------- repo + per-task state\\ndef git(args, cwd):\\n    try:\\n        r = subprocess.run([\\"git\\"] + args, cwd=cwd, capture_output=True, text=True, timeout=15)\\n        return r.stdout.strip() if r.returncode == 0 else \\"\\"\\n    except Exception:  # noqa: BLE001\\n        return \\"\\"\\n\\n\\ndef repo_root():\\n    cands = []\\n    for fr in inspect.stack():\\n        cwd = fr.frame.f_locals.get(\\"_orig_cwd\\")\\n        if isinstance(cwd, str):\\n            cands.append(cwd)\\n    cands += [os.environ.get(\\"CODE_MAP_ROOT\\"), \\"/workspace\\", os.environ.get(\\"PWD\\"), os.getcwd()]\\n    for c in cands:\\n        if c and os.path.isdir(c) and not os.path.basename(c).startswith(\\"tmp\\"):\\n            return git([\\"rev-parse\\", \\"--show-toplevel\\"], c) or c\\n    return os.getcwd()\\n\\n\\ndef state_key(root):\\n    head = git([\\"rev-parse\\", \\"HEAD\\"], root)\\n    try:\\n        st = os.stat(os.path.join(root, \\".git\\"))\\n        extra = f\\"{st.st_ino}-{st.st_ctime}\\"\\n    except OSError:\\n        extra = \\"\\"\\n    return hashlib.md5(f\\"{root}|{head}|{extra}\\".encode()).hexdigest()[:16]\\n\\n\\ndef bump_counter(key, cmd):\\n    path = f\\"/tmp/.codemap_{key}.json\\"\\n    try:\\n        st = json.load(open(path))\\n    except Exception:  # noqa: BLE001\\n        st = {\\"n\\": 0}\\n    if cmd != \\"status\\":\\n        st[\\"n\\"] += 1\\n    try:\\n        json.dump(st, open(path, \\"w\\"))\\n    except Exception:  # noqa: BLE001\\n        pass\\n    return st[\\"n\\"]\\n\\n\\n# ---------------------------------------------------------------- index\\ndef is_test(rel):\\n    parts = rel.replace(\\"\\\\\\\\\\", \\"/\\").split(\\"/\\")\\n    base = parts[-1]\\n    return any(p in (\\"tests\\", \\"test\\", \\"testing\\") for p in parts[:-1]) or base.startswith(\\"test_\\") or \\\\\\n        base.endswith(\\"_test.py\\") or base == \\"conftest.py\\"\\n\\n\\ndef module_name(rel):\\n    mod = rel[:-3].replace(os.sep, \\".\\").replace(\\"/\\", \\".\\")\\n    if mod.endswith(\\".__init__\\"):\\n        mod = mod[: -len(\\".__init__\\")]\\n    for prefix in (\\"src.\\", \\"lib.\\"):\\n        if mod.startswith(prefix):\\n            mod = mod[len(prefix):]\\n    return mod\\n\\n\\nclass Indexer(ast.NodeVisitor):\\n    def __init__(self, mod, rel, lines, idx):\\n        self.mod, self.rel, self.lines, self.idx = mod, rel, lines, idx\\n        self.stack = []  # (qual, kind)\\n        self.imports = {}\\n\\n    def cur(self):\\n        return self.stack[-1][0] if self.stack else f\\"{self.mod}.<module>\\"\\n\\n    def cur_class(self):\\n        for q, k in reversed(self.stack):\\n            if k == \\"class\\":\\n                return q\\n        return None\\n\\n    def visit_Import(self, node):\\n        for a in node.names:\\n            self.imports[a.asname or a.name.split(\\".\\")[0]] = a.name if a.asname else a.name.split(\\".\\")[0]\\n\\n    def visit_ImportFrom(self, node):\\n        base = node.module or \\"\\"\\n        if node.level:\\n            pkg = self.mod.split(\\".\\")\\n            if not self.rel.endswith(\\"__init__.py\\"):\\n                pkg = pkg[:-1]\\n            pkg = pkg[: len(pkg) - (node.level - 1)] if node.level > 1 else pkg\\n            base = \\".\\".join(pkg + ([base] if base else []))\\n        for a in node.names:\\n            self.imports[a.asname or a.name] = f\\"{base}.{a.name}\\" if base else a.name\\n\\n    def _def(self, node, kind):\\n        q = f\\"{self.cur()}.{node.name}\\" if self.stack else f\\"{self.mod}.{node.name}\\"\\n        sig = self.lines[node.lineno - 1].strip()[:150] if node.lineno - 1 < len(self.lines) else \\"\\"\\n        doc = ast.get_docstring(node) or \\"\\"\\n        bases = [b.id if isinstance(b, ast.Name) else b.attr if isinstance(b, ast.Attribute) else \\"\\" for b in\\n                 getattr(node, \\"bases\\", [])]\\n        idents = set()\\n        if kind != \\"class\\":\\n            for n in ast.walk(node):\\n                if isinstance(n, ast.Name):\\n                    idents.add(n.id)\\n                elif isinstance(n, ast.Attribute):\\n                    idents.add(n.attr)\\n        self.idx[\\"defs\\"].append(dict(q=q, short=node.name, kind=kind, rel=self.rel, start=node.lineno,\\n                                     end=getattr(node, \\"end_lineno\\", node.lineno), sig=sig,\\n                                     doc=doc.strip().split(\\"\\\\n\\")[0][:120], cls=self.cur_class(), bases=bases,\\n                                     test=is_test(self.rel), idents=sorted(idents)[:200]))\\n        self.stack.append((q, kind))\\n        self.generic_visit(node)\\n        self.stack.pop()\\n\\n    def visit_FunctionDef(self, node):\\n        self._def(node, \\"def\\")\\n\\n    visit_AsyncFunctionDef = visit_FunctionDef\\n\\n    def visit_ClassDef(self, node):\\n        self._def(node, \\"class\\")\\n\\n    def visit_Call(self, node):\\n        f = node.func\\n        name = base = None\\n        if isinstance(f, ast.Name):\\n            name = f.id\\n        elif isinstance(f, ast.Attribute):\\n            name = f.attr\\n            if isinstance(f.value, ast.Name):\\n                base = f.value.id\\n        if name:\\n            self.idx[\\"calls\\"].append((self.cur(), name, base, self.rel, node.lineno, self.mod, self.cur_class()))\\n        self.generic_visit(node)\\n\\n\\ndef build_index(root):\\n    idx = {\\"defs\\": [], \\"calls\\": [], \\"imports\\": {}, \\"files\\": []}\\n    n = 0\\n    for dp, dns, fns in os.walk(root):\\n        dns[:] = sorted(d for d in dns if d not in SKIP_DIRS and not d.startswith(\\".\\"))\\n        for fn in sorted(fns):\\n            if not fn.endswith(\\".py\\"):\\n                continue\\n            n += 1\\n            if n > MAX_FILES:\\n                break\\n            full = os.path.join(dp, fn)\\n            rel = os.path.relpath(full, root)\\n            idx[\\"files\\"].append(rel)\\n            try:\\n                src = open(full, encoding=\\"utf-8\\", errors=\\"replace\\").read()\\n                tree = ast.parse(src)\\n            except Exception:  # noqa: BLE001\\n                continue\\n            mod = module_name(rel)\\n            v = Indexer(mod, rel, src.splitlines(), idx)\\n            v.visit(tree)\\n            idx[\\"imports\\"][mod] = v.imports\\n    by_q = {d[\\"q\\"]: d for d in idx[\\"defs\\"]}\\n    by_short = collections.defaultdict(list)\\n    for d in idx[\\"defs\\"]:\\n        by_short[d[\\"short\\"]].append(d[\\"q\\"])\\n    # resolve calls -> edges\\n    fwd, rev = collections.defaultdict(list), collections.defaultdict(list)\\n    for caller, name, base, rel, line, mod, cls in idx[\\"calls\\"]:\\n        targets = []\\n        if base in (\\"self\\", \\"cls\\") and cls:\\n            cand = f\\"{cls}.{name}\\"\\n            if cand in by_q:\\n                targets = [cand]\\n            else:\\n                targets = [q for q in by_short.get(name, []) if by_q[q][\\"cls\\"]][:3]\\n        else:\\n            imp = idx[\\"imports\\"].get(mod, {})\\n            if base and base in imp and f\\"{imp[base]}.{name}\\" in by_q:\\n                targets = [f\\"{imp[base]}.{name}\\"]\\n            elif not base and f\\"{mod}.{name}\\" in by_q:\\n                targets = [f\\"{mod}.{name}\\"]\\n            elif not base and name in imp and imp[name] in by_q:\\n                targets = [imp[name]]\\n            elif not base and name in imp:\\n                tail = imp[name].split(\\".\\")[-1]\\n                targets = [q for q in by_short.get(tail, []) if q.endswith(\\".\\" + tail)][:2]\\n            elif name not in COMMON:\\n                c = by_short.get(name, [])\\n                targets = c[:3] if len(c) <= 3 else []\\n        caller_is_test = is_test(rel)\\n        targets = [t for t in targets if caller_is_test or not by_q[t][\\"test\\"]]\\n        for t in targets:\\n            if by_q[t][\\"kind\\"] == \\"class\\":\\n                init = f\\"{t}.__init__\\"\\n                t = init if init in by_q else t\\n            fwd[caller].append((t, rel, line))\\n            rev[t].append((caller, rel, line))\\n    idx[\\"fwd\\"], idx[\\"rev\\"], idx[\\"by_short\\"] = dict(fwd), dict(rev), dict(by_short)\\n    idx[\\"by_q\\"] = by_q\\n    return idx\\n\\n\\ndef load_index(root, key):\\n    path = f\\"/tmp/.codemap_{key}.pkl\\"\\n    try:\\n        with open(path, \\"rb\\") as f:\\n            return pickle.load(f)\\n    except Exception:  # noqa: BLE001\\n        pass\\n    idx = build_index(root)\\n    try:\\n        with open(path, \\"wb\\") as f:\\n            pickle.dump(idx, f)\\n    except Exception:  # noqa: BLE001\\n        pass\\n    return idx\\n\\n\\n# ---------------------------------------------------------------- helpers\\ndef resolve(idx, name, tests=False):\\n    name = name.strip().strip(\\"`\'\\\\\\"()\\").rstrip(\\":\\")\\n    by_q = idx[\\"by_q\\"]\\n    if name in by_q:\\n        return [name]\\n    hits = [q for q in by_q if q.endswith(\\".\\" + name)]\\n    if not hits and \\".\\" not in name:\\n        hits = list(idx[\\"by_short\\"].get(name, []))\\n    if not hits:\\n        low = name.lower()\\n        hits = [q for q in by_q if q.lower().endswith(\\".\\" + low)]\\n    if not tests:\\n        nt = [q for q in hits if not by_q[q][\\"test\\"]]\\n        hits = nt or hits\\n    hits.sort(key=lambda q: (by_q[q][\\"test\\"], q.count(\\".\\"), len(q)))\\n    return hits\\n\\n\\ndef loc(d):\\n    return f\\"{d[\'rel\']}:{d[\'start\']}-{d[\'end\']}\\"\\n\\n\\ndef enclosing(idx, rel, line):\\n    best = None\\n    for d in idx[\\"defs\\"]:\\n        if d[\\"rel\\"] == rel and d[\\"start\\"] <= line <= d[\\"end\\"] and (best is None or d[\\"start\\"] >= best[\\"start\\"]):\\n            best = d\\n    return best[\\"q\\"] if best else module_name(rel)\\n\\n\\ndef no_match(name):\\n    emit(f\\"no definition matching {name!r}. Try `search` with a regex, or a shorter name.\\")\\n\\n\\ndef short_list(items, k, tests=True):\\n    out, seen = [], set()\\n    for it in items:\\n        if not tests and is_test(it[1]):\\n            continue\\n        key = it[0]\\n        if key not in seen:\\n            seen.add(key)\\n            out.append(it)\\n    return out[:k]\\n\\n\\n# ---------------------------------------------------------------- commands\\ndef cmd_search(root, idx, pattern, tests):\\n    try:\\n        rx = re.compile(pattern)\\n    except re.error:\\n        rx = re.compile(re.escape(pattern))\\n    hits = 0\\n    for rel in idx[\\"files\\"]:\\n        if not tests and is_test(rel):\\n            continue\\n        try:\\n            lines = open(os.path.join(root, rel), encoding=\\"utf-8\\", errors=\\"replace\\").read().splitlines()\\n        except OSError:\\n            continue\\n        for i, l in enumerate(lines, 1):\\n            if rx.search(l):\\n                hits += 1\\n                if hits <= 30:\\n                    emit(f\\"{rel}:{i}  [{enclosing(idx, rel, i)}]  | {l.strip()[:120]}\\")\\n    if hits == 0:\\n        emit(f\\"no matches for {pattern!r}\\" + (\\"\\" if tests else \\" outside tests (add --tests to include tests)\\"))\\n    elif hits > 30:\\n        emit(f\\"... {hits - 30} more matches; make the pattern more specific\\")\\n\\n\\ndef cmd_show(root, idx, rel, a, b):\\n    rel = rel.replace(\\"/workspace/\\", \\"\\").lstrip(\\"./\\") if not os.path.isabs(rel) else os.path.relpath(rel, root)\\n    try:\\n        lines = open(os.path.join(root, rel), encoding=\\"utf-8\\", errors=\\"replace\\").read().splitlines()\\n    except OSError:\\n        emit(f\\"cannot open {rel}\\")\\n        return\\n    a = max(1, int(a))\\n    b = min(len(lines), int(b), a + 99)\\n    emit(f\\"{rel} lines {a}-{b} of {len(lines)}  (inside {enclosing(idx, rel, a)})\\")\\n    for i in range(a, b + 1):\\n        emit(f\\"{i:5d}  {lines[i - 1]}\\")\\n\\n\\ndef cmd_find(idx, name, tests):\\n    hits = resolve(idx, name, tests)\\n    if not hits:\\n        return no_match(name)\\n    for q in hits[:12]:\\n        d = idx[\\"by_q\\"][q]\\n        emit(f\\"{q}  [{d[\'kind\']}]  {loc(d)}  | {d[\'sig\']}\\")\\n    if len(hits) > 12:\\n        emit(f\\"... {len(hits) - 12} more\\")\\n\\n\\ndef tests_for(root, idx, short, k=5):\\n    out = []\\n    rx = re.compile(r\\"\\\\b\\" + re.escape(short) + r\\"\\\\b\\")\\n    for rel in idx[\\"files\\"]:\\n        if not is_test(rel):\\n            continue\\n        try:\\n            src = open(os.path.join(root, rel), encoding=\\"utf-8\\", errors=\\"replace\\").read()\\n        except OSError:\\n            continue\\n        n = len(rx.findall(src))\\n        if n:\\n            out.append((n, rel))\\n    out.sort(reverse=True)\\n    return out[:k]\\n\\n\\ndef cmd_trace(root, idx, name, tests):\\n    hits = resolve(idx, name, tests)\\n    if not hits:\\n        return no_match(name)\\n    q = hits[0]\\n    d = idx[\\"by_q\\"][q]\\n    emit(f\\"DEFINITION  {q}  [{d[\'kind\']}]  {loc(d)}\\")\\n    emit(f\\"  {d[\'sig\']}\\" + (f\\"   # {d[\'doc\']}\\" if d[\\"doc\\"] else \\"\\"))\\n    if len(hits) > 1:\\n        emit(\\"  other matches: \\" + \\", \\".join(hits[1:5]))\\n    if d[\\"kind\\"] == \\"class\\":\\n        meths = [x for x in idx[\\"defs\\"] if x[\\"cls\\"] == q][:15]\\n        emit(\\"  methods: \\" + \\", \\".join(f\\"{m[\'short\']}:{m[\'start\']}\\" for m in meths))\\n        sub = [x[\\"q\\"] for x in idx[\\"defs\\"] if x[\\"kind\\"] == \\"class\\" and d[\\"short\\"] in x[\\"bases\\"]][:6]\\n        if sub:\\n            emit(\\"  subclasses: \\" + \\", \\".join(sub))\\n    allc = idx[\\"rev\\"].get(q, [])\\n    callers = short_list(allc, 12, tests)\\n    ntest = len({c for c, rel, _ in allc if is_test(rel)})\\n    emit(f\\"CALLERS ({len(callers)} in source\\" + (f\\"; {ntest} test functions also call it\\" if ntest and not tests else \\"\\") + \\")\\")\\n    for c, rel, line in callers:\\n        emit(f\\"  {c}  @ {rel}:{line}\\")\\n    callees = short_list(idx[\\"fwd\\"].get(q, []), 14)\\n    emit(f\\"CALLEES ({len(idx[\'fwd\'].get(q, []))})\\")\\n    for c, rel, line in callees:\\n        cd = idx[\\"by_q\\"].get(c)\\n        emit(f\\"  {c}  def {loc(cd) if cd else \'?\'}  (called at line {line})\\")\\n    sims = similar_list(idx, q, 5)\\n    if sims:\\n        emit(\\"OVERRIDES / SIMILAR\\")\\n        for s, why in sims:\\n            emit(f\\"  {s}  {loc(idx[\'by_q\'][s])}  ({why})\\")\\n    t = tests_for(root, idx, d[\\"short\\"])\\n    emit(\\"TESTS  \\" + (\\", \\".join(f\\"{rel} ({n})\\" for n, rel in t) if t else \\"none reference it by name\\"))\\n\\n\\ndef cmd_callers(idx, name, tests):\\n    hits = resolve(idx, name, tests)\\n    if not hits:\\n        return no_match(name)\\n    q = hits[0]\\n    emit(f\\"callers of {q}  ({loc(idx[\'by_q\'][q])})\\")\\n    lvl1 = short_list(idx[\\"rev\\"].get(q, []), 15, tests)\\n    if not lvl1:\\n        emit(\\"  none found statically (may be used via a decorator, getattr, callback, or only from tests)\\")\\n    for c, rel, line in lvl1:\\n        emit(f\\"  <- {c}  @ {rel}:{line}\\")\\n        for c2, rel2, line2 in short_list(idx[\\"rev\\"].get(c, []), 3, tests):\\n            emit(f\\"       <- {c2}  @ {rel2}:{line2}\\")\\n\\n\\ndef cmd_callees(idx, name, tests):\\n    hits = resolve(idx, name, tests)\\n    if not hits:\\n        return no_match(name)\\n    q = hits[0]\\n    emit(f\\"{q}  ({loc(idx[\'by_q\'][q])}) calls:\\")\\n    for c, rel, line in short_list(idx[\\"fwd\\"].get(q, []), 25):\\n        cd = idx[\\"by_q\\"].get(c)\\n        emit(f\\"  -> {c}  def {loc(cd) if cd else \'?\'}  (line {line})\\")\\n    if not idx[\\"fwd\\"].get(q):\\n        emit(\\"  (no calls to functions defined in this repository)\\")\\n\\n\\ndef bfs(idx, srcs, dsts, graph, max_depth=7):\\n    dsts = set(dsts)\\n    prev = {s: None for s in srcs}\\n    frontier = list(srcs)\\n    for _ in range(max_depth):\\n        nxt = []\\n        for u in frontier:\\n            for v, rel, line in idx[graph].get(u, []):\\n                if v not in prev:\\n                    prev[v] = (u, rel, line)\\n                    if v in dsts:\\n                        chain, cur = [], v\\n                        while prev[cur] is not None:\\n                            p, r, l = prev[cur]\\n                            chain.append((p, cur, r, l))\\n                            cur = p\\n                        return list(reversed(chain))\\n                    nxt.append(v)\\n        frontier = nxt\\n    return None\\n\\n\\ndef cmd_path(idx, a, b, tests):\\n    A, B = resolve(idx, a, True)[:6], resolve(idx, b, True)[:6]\\n    if not A or not B:\\n        return no_match(a if not A else b)\\n    chain = bfs(idx, A, B, \\"fwd\\")\\n    if chain:\\n        emit(f\\"call chain {a} -> {b}:\\")\\n        for p, c, rel, line in chain:\\n            emit(f\\"  {p}  --calls at {rel}:{line}-->  {c}\\")\\n        return\\n    chain = bfs(idx, B, A, \\"fwd\\")\\n    if chain:\\n        emit(f\\"no path {a} -> {b}, but {b} reaches {a}:\\")\\n        for p, c, rel, line in chain:\\n            emit(f\\"  {p}  --calls at {rel}:{line}-->  {c}\\")\\n        return\\n    ra = {x[0] for x in idx[\\"rev\\"].get(A[0], [])}\\n    rb = {x[0] for x in idx[\\"rev\\"].get(B[0], [])}\\n    common = sorted(ra & rb)[:5]\\n    emit(f\\"no static call chain between {A[0]} and {B[0]}\\" +\\n         (f\\"; both are called by: {\', \'.join(common)}\\" if common else \\". Try `callers` on each.\\"))\\n\\n\\nGENERIC = {\\"__init__\\", \\"__repr__\\", \\"__str__\\", \\"__call__\\", \\"__eq__\\", \\"__hash__\\", \\"__iter__\\", \\"__len__\\",\\n           \\"__getitem__\\", \\"__enter__\\", \\"__exit__\\", \\"__aenter__\\", \\"__aexit__\\", \\"__rich__\\", \\"__rich_console__\\",\\n           \\"__rich_measure__\\", \\"main\\", \\"run\\", \\"setup\\"}\\n\\n\\ndef similar_list(idx, q, k):\\n    d = idx[\\"by_q\\"][q]\\n    mod = d[\\"q\\"].rsplit(\\".\\", 2 if d[\\"cls\\"] else 1)[0]\\n    my_bases = set(idx[\\"by_q\\"][d[\\"cls\\"]][\\"bases\\"]) if d[\\"cls\\"] in idx[\\"by_q\\"] else set()\\n    out = []\\n    for o in idx[\\"defs\\"]:\\n        if o[\\"q\\"] == q or o[\\"test\\"] or o[\\"kind\\"] != d[\\"kind\\"] or o[\\"short\\"] != d[\\"short\\"]:\\n            continue\\n        same_mod = o[\\"rel\\"] == d[\\"rel\\"]\\n        ob = set(idx[\\"by_q\\"][o[\\"cls\\"]][\\"bases\\"]) if o[\\"cls\\"] in idx[\\"by_q\\"] else set()\\n        sibling = bool(my_bases & ob) or (d[\\"cls\\"] and idx[\\"by_q\\"][o[\\"cls\\"]][\\"short\\"] in my_bases if o[\\"cls\\"] in idx[\\"by_q\\"] else False)\\n        if d[\\"short\\"] in GENERIC and not (same_mod or sibling):\\n            continue\\n        score = 3 if same_mod else 2 if sibling else 1\\n        out.append((score, o[\\"q\\"], \\"same name, same file\\" if same_mod else \\"same name, sibling class\\" if sibling\\n                    else \\"same name elsewhere\\"))\\n    if d[\\"kind\\"] != \\"class\\" and d[\\"idents\\"]:\\n        a = set(d[\\"idents\\"])\\n        for o in idx[\\"defs\\"]:\\n            if o[\\"q\\"] == q or o[\\"test\\"] or o[\\"kind\\"] == \\"class\\" or not o[\\"idents\\"]:\\n                continue\\n            b = set(o[\\"idents\\"])\\n            j = len(a & b) / max(1, len(a | b))\\n            if j >= 0.45:\\n                out.append((j, o[\\"q\\"], f\\"shares {int(j * 100)}% of identifiers\\"))\\n    out.sort(key=lambda x: -x[0])\\n    seen, res = set(), []\\n    for s_, oq, why in out:\\n        if oq not in seen:\\n            seen.add(oq)\\n            res.append((oq, why))\\n    return res[:k]\\n\\n\\ndef cmd_similar(idx, name, tests):\\n    hits = resolve(idx, name, tests)\\n    if not hits:\\n        return no_match(name)\\n    q = hits[0]\\n    res = similar_list(idx, q, 10)\\n    emit(f\\"places similar to {q}  ({loc(idx[\'by_q\'][q])}):\\")\\n    for oq, why in res:\\n        emit(f\\"  {oq}  {loc(idx[\'by_q\'][oq])}  ({why})\\")\\n    if not res:\\n        emit(\\"  none found\\")\\n\\n\\ndef cmd_tests(root, idx, name):\\n    short = name.strip().split(\\".\\")[-1]\\n    t = tests_for(root, idx, short, 8)\\n    if not t:\\n        emit(f\\"no test file mentions {short!r}\\")\\n        return\\n    for n, rel in t:\\n        fns = [d[\\"short\\"] for d in idx[\\"defs\\"] if d[\\"rel\\"] == rel and d[\\"short\\"].startswith(\\"test\\")]\\n        emit(f\\"{rel}  ({n} mentions; {len(fns)} tests)  run: python -m pytest {rel} -x -q\\")\\n\\n\\ndef cmd_outline(root, idx, rel):\\n    rel = rel.replace(\\"/workspace/\\", \\"\\").lstrip(\\"./\\")\\n    ds = sorted((d for d in idx[\\"defs\\"] if d[\\"rel\\"] == rel), key=lambda d: d[\\"start\\"])\\n    if not ds:\\n        emit(f\\"no definitions indexed for {rel}\\")\\n        return\\n    emit(f\\"module {module_name(rel)}\\")\\n    for d in ds[:80]:\\n        depth = d[\\"q\\"].count(\\".\\") - module_name(rel).count(\\".\\") - 1\\n        emit(f\\"{\'  \' * depth}{d[\'short\']}  {d[\'start\']}-{d[\'end\']}\\")\\n\\n\\ndef main(argv):\\n    args = [a for a in argv if a != \\"--\\"]\\n    tests = \\"--tests\\" in args\\n    args = [a for a in args if a != \\"--tests\\"]\\n    if not args or args[0] not in (\\"search\\", \\"show\\", \\"find\\", \\"trace\\", \\"callers\\", \\"callees\\", \\"path\\", \\"similar\\",\\n                                   \\"tests\\", \\"outline\\", \\"status\\"):\\n        print(__doc__)\\n        return\\n    cmd = args[0]\\n    root = repo_root()\\n    key = state_key(root)\\n    n = bump_counter(key, cmd)\\n    if cmd == \\"status\\":\\n        print(f\\"code-map calls used: {n} of {BUDGET}\\")\\n        return\\n    if n > BUDGET:\\n        print(f\\"LOCALIZER BUDGET REACHED ({BUDGET} code-map calls). Do not call any more tools. \\"\\n              \\"Write your final diagnosis now, using what you have found.\\")\\n        return\\n    idx = load_index(root, key)\\n    try:\\n        if cmd == \\"search\\" and len(args) >= 2:\\n            cmd_search(root, idx, \\" \\".join(args[1:]), tests)\\n        elif cmd == \\"show\\" and len(args) >= 4:\\n            cmd_show(root, idx, args[1], args[2], args[3])\\n        elif cmd == \\"show\\" and len(args) == 3 and \\"-\\" in args[2]:\\n            a, b = args[2].split(\\"-\\", 1)\\n            cmd_show(root, idx, args[1], a, b)\\n        elif cmd == \\"find\\" and len(args) >= 2:\\n            cmd_find(idx, args[1], tests)\\n        elif cmd == \\"trace\\" and len(args) >= 2:\\n            cmd_trace(root, idx, args[1], tests)\\n        elif cmd == \\"callers\\" and len(args) >= 2:\\n            cmd_callers(idx, args[1], tests)\\n        elif cmd == \\"callees\\" and len(args) >= 2:\\n            cmd_callees(idx, args[1], tests)\\n        elif cmd == \\"path\\" and len(args) >= 3:\\n            cmd_path(idx, args[1], args[2], tests)\\n        elif cmd == \\"similar\\" and len(args) >= 2:\\n            cmd_similar(idx, args[1], tests)\\n        elif cmd == \\"tests\\" and len(args) >= 2:\\n            cmd_tests(root, idx, args[1])\\n        elif cmd == \\"outline\\" and len(args) >= 2:\\n            cmd_outline(root, idx, args[1])\\n        else:\\n            emit(f\\"bad arguments for {cmd!r}.\\")\\n            emit(__doc__)\\n    except Exception as e:  # noqa: BLE001\\n        emit(f\\"code-map error: {type(e).__name__}: {e}\\")\\n    if BUDGET - n <= 4:\\n        emit(f\\"[code-map: {BUDGET - n} calls left before you must write the diagnosis]\\")\\n    flush()\\n\\n\\nif __name__ == \\"__main__\\":\\n    main(sys.argv[1:])\\n", "sub_agents/fixer.yaml": "name: fixer_agent\\ndescription: Applies and verifies the fix described in the diagnosis, then submits the patch.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/fixer.md\\ninclude_contents: none\\ntools:\\n  - run_command\\n  - edit_file\\n  - write_file\\n  - get_status\\n  - submit_patch\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n", "sub_agents/localizer.yaml": "name: localizer_agent\\ndescription: Traces the code relationships behind the issue and writes a structured brief for the fixer. Never edits files.\\nmodel: gemma-4-31b-it-qat-w4a16-ct\\ninstruction: !include ../prompts/localizer.md\\ntools: []\\nskills:\\n  - skills/code-map\\noutput_key: diagnosis\\ndisallow_transfer_to_parent: true\\ndisallow_transfer_to_peers: true\\ngenerate_content_config: !include ../configs/sampling.yaml\\n"}')
if CFG["SUBMISSION_DIR"]:
    SUB = pathlib.Path(CFG["SUBMISSION_DIR"])
elif CFG["VARIANT"] in ("v4_pipeline", "v5_graph", "v6_trace"):
    SUB = W / f"{CFG['VARIANT']}_submission"
    shutil.rmtree(SUB, ignore_errors=True)
    for rel, txt in {"v4_pipeline": V4_FILES, "v5_graph": V5_FILES, "v6_trace": V6_FILES}[CFG["VARIANT"]].items():
        (SUB / rel).parent.mkdir(parents=True, exist_ok=True)
        (SUB / rel).write_text(txt)
else:
    SAMPLE = DATA / "sample_submission"
    SUB = W / f"{CFG['VARIANT']}_submission"
    shutil.rmtree(SUB, ignore_errors=True)
    for d in ("prompts", "configs", "sub_agents"):
        (SUB / d).mkdir(parents=True)
    for f in ("system.md", "analyzer.md"):
        shutil.copy(SAMPLE / "prompts" / f, SUB / "prompts" / f)
    (SUB / "configs" / "sampling.yaml").write_text(
        "temperature: 0.2\ntop_p: 0.95\ntop_k: 40\nmax_output_tokens: 8192\n"
        "thinking_config:\n  include_thoughts: false\n  thinking_budget: 0\n")
    tools = ["run_command", "read_file", "edit_file", "write_file", "get_status", "submit_patch",
             "get_code_neighbors", "search_similar_code", "get_code_subgraph"]
    analyzer_read = "read_file"
    if CFG["VARIANT"] in ("v2_sed", "v2b_budget80", "v3_verify"):
        # ONE change vs baseline: the read channel. read_file's line-range args arrive malformed in ~47% of calls
        # (e.g. key 'start_line\"'), are silently ignored, and the agent re-reads lines 1-150 in loops.
        tools.remove("read_file")
        analyzer_read = "run_command"
        sp = SUB / "prompts" / "system.md"
        t0 = sp.read_text()
        old = "using `read_file` or search tools"
        assert old in t0, "sample system.md changed; update the v2 replacement"
        sp.write_text(t0.replace(old, "with `run_command` using `grep -n PATTERN path` and `sed -n 'START,ENDp' path` "
                                      "(read at most ~80 lines at a time), or search tools"))
        ap = SUB / "prompts" / "analyzer.md"
        a0 = ap.read_text()
        olda = "`get_code_subgraph`, and `read_file`"
        assert olda in a0, "sample analyzer.md changed; update the v2 replacement"
        ap.write_text(a0.replace(olda, "`get_code_subgraph`, and `run_command` (read-only: only `grep -n` and "
                                       "`sed -n 'START,ENDp' path`; never modify files)"))
    if CFG["VARIANT"] == "v3_verify":
        # ONE change vs v2: an explicit budget plan that reserves calls for editing + one targeted test run.
        # v2 evidence: 47/129 tasks = wrong fix never tested; only 9 of them ran any test; median 37/40 calls used.
        sp = SUB / "prompts" / "system.md"
        sp.write_text(sp.read_text().rstrip() + "\n\n" + V3_BLOCK)
    (SUB / "agent.yaml").write_text(
        f"name: swe_baseline_agent\nmodel: {TARGET}\ninstruction: !include prompts/system.md\ntools:\n"
        + "".join(f"  - {t}\n" for t in tools)
        + "  - agent_tool:\n      config_path: sub_agents/code_analyzer.yaml\n      skip_summarization: false\n"
        "generate_content_config: !include configs/sampling.yaml\n")
    (SUB / "sub_agents" / "code_analyzer.yaml").write_text(
        "name: code_analyzer_agent\ndescription: Analyzes repository source files and symbol graphs to locate root causes.\n"
        f"model: {TARGET}\ninstruction: !include ../prompts/analyzer.md\ntools:\n"
        f"  - {analyzer_read}\n  - search_similar_code\n  - get_code_neighbors\n  - get_code_subgraph\n"
        "generate_content_config: !include ../configs/sampling.yaml\n")
    calls, turns = (80, 160) if CFG["VARIANT"] == "v2b_budget80" else (40, 100)
    (SUB / "eval_config.yaml").write_text(
        f"evaluation:\n  timeout_seconds: 180\n  max_tool_calls: {calls}\n  max_time_minutes: 4.5\n  max_turns: {turns}\n")
if (W / "submission.zip").exists():
    (W / "submission.zip").unlink()
shutil.make_archive(str(W / "submission"), "zip", SUB)
log("submission under test:", SUB, sorted(str(p.relative_to(SUB)) for p in SUB.rglob("*") if p.is_file()))

# ------------------------------------------------------------------ 3. vLLM exactly like the scorer
import litellm  # noqa: E402
import torch  # noqa: E402
import yaml  # noqa: E402

litellm.drop_params = True
from adk_submission import VllmConfig, VllmServer, discover_adapters  # noqa: E402
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS, EvalConfig, build_submission_limits  # noqa: E402
from swegemma.evaluate import Evaluator  # noqa: E402
from swegemma.models.discovery import validate_single_declared_model  # noqa: E402

adapters = discover_adapters(str(SUB), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
log("adapters:", list(getattr(adapters, "adapters", {}) or {}))
server = VllmServer(VllmConfig(
    model=MODEL_PATH, port=8000, host="127.0.0.1", tool_call_parser="gemma4", reasoning_parser="gemma4",
    default_chat_template_kwargs={"enable_thinking": True}, max_model_len=32768,
    dtype="bfloat16" if torch.cuda.is_bf16_supported() else "auto", gpu_memory_utilization=0.80,
    enable_auto_tool_choice=True, enable_lora=True, max_loras=8, max_lora_rank=128,
    tensor_parallel_size=4, startup_timeout=60 * 25), adapter_manifest=adapters)
t = time.time()
server.start()
log(f"vLLM up on {server.base_url} after {time.time() - t:.0f}s")
declared = validate_single_declared_model(SUB)
models = server.create_model_registry(aliases=[declared, TARGET], model_prefix="openai/", api_key="EMPTY")

# ------------------------------------------------------------------ 4. agent sandbox offline (like network_mode=none)
for k in ("http_proxy", "https_proxy", "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "all_proxy"):
    os.environ[k] = "http://127.0.0.1:9"
os.environ["NO_PROXY"] = os.environ["no_proxy"] = "localhost,127.0.0.1"
os.environ["PIP_NO_INDEX"] = "1"

# ------------------------------------------------------------------ 5. evaluate in chunks, sequential, scorer budgets
ev = yaml.safe_load((SUB / "eval_config.yaml").read_text()) if (SUB / "eval_config.yaml").exists() else {}
ev = (ev or {}).get("evaluation", ev or {})
tasks = [json.loads(l) for l in open(tasks_path) if l.strip()]
if CFG["task_ids"]:
    ids = list(CFG["task_ids"])
else:  # interleave repos so any prefix is a stratified sample
    rng = random.Random(CFG["seed"])
    by_repo = {}
    for tk in tasks:
        by_repo.setdefault(tk["repo"], []).append(tk["instance_id"])
    for v in by_repo.values():
        rng.shuffle(v)
    ids, pools = [], [list(v) for v in by_repo.values()]
    total = sum(len(p) for p in pools)
    while len(ids) < total:
        for p in sorted(pools, key=len, reverse=True):
            if p:
                ids.append(p.pop())
(W / "task_ids_order.json").write_text(json.dumps(ids, indent=1))
limits, gen = build_submission_limits()
CFG["results"] = CFG["results"] or f"official_l4_{CFG['VARIANT']}" + ("_dev" if CFG["DEVSET"] else "")
ROOT = W / CFG["results"]
done = []
for c in range(0, len(ids), CFG["chunk_size"]):
    chunk = ids[c:c + CFG["chunk_size"]]
    left_h = CFG["session_budget_h"] - (time.time() - T0) / 3600
    if left_h < len(chunk) * CFG["est_task_min"] / 60:
        log(f"STOP: {left_h:.2f} h left, not enough for another chunk ({len(done)} tasks done)")
        break
    turns = ev.get("max_turns", ev.get("max_llm_calls"))
    cfg = EvalConfig(
        tasks_path=pathlib.Path(tasks_path), snapshots_dir=SNAPS, results_dir=ROOT / f"chunk_{c:03d}",
        submission_dir=SUB, models=models, sandbox="subprocess", wheels_dir=DATA / "wheels",
        graph_dir=str(DATA / "graphs"), embeddings_dir=str(DATA / "embeddings"),
        timeout_seconds=ev.get("timeout_seconds"), max_time_minutes=ev.get("max_time_minutes"),
        max_tool_calls=ev.get("max_tool_calls"), max_turns=int(turns) if turns is not None else None,
        limits=limits, generation_constraints=gen, adapter_manifest=adapters,
        context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
        events_compaction_config=EventsCompactionConfig(compaction_interval=15, overlap_size=2,
                                                        token_threshold=32768, event_retention_size=5),
        task_ids=chunk, concurrency=1, display_mode="quiet", verbose=False)
    t = time.time()
    try:
        res = asyncio.run(Evaluator(cfg).run())
        log(f"chunk {c // CFG['chunk_size']}: {repr(res)[:300]} ({(time.time() - t) / 60:.1f} min)")
    except Exception as e:  # noqa: BLE001
        log(f"chunk {c // CFG['chunk_size']} FAILED: {type(e).__name__}: {e}")
    done += chunk

# ------------------------------------------------------------------ 6. merge chunks into one results dir
MERGED = W / "merged"
shutil.rmtree(MERGED, ignore_errors=True)
for sub in ("traces", "patches", "test_outputs", "logs"):
    (MERGED / sub).mkdir(parents=True)
with open(MERGED / "task_results.jsonl", "w") as out:
    for ch in sorted(ROOT.glob("chunk_*")):
        if (ch / "task_results.jsonl").exists():
            out.write((ch / "task_results.jsonl").read_text())
        for sub in ("traces", "patches", "test_outputs", "logs"):
            for f in (ch / sub).glob("*"):
                shutil.copy(f, MERGED / sub / f.name)
rows = [json.loads(l) for l in open(MERGED / "task_results.jsonl") if l.strip()]
log(f"RESULT: {sum(r.get('resolved', False) for r in rows)}/{len(rows)} resolved")

# ------------------------------------------------------------------ 7. failure analysis + package
ana = next((p for p in [pathlib.Path("trace_analyzer.py"),
                        *map(pathlib.Path, glob.glob("/kaggle/input/**/trace_analyzer.py", recursive=True))]
            if p.exists()), None)
if ana:
    sh(f"{sys.executable} {ana} --results {MERGED} --tasks {tasks_path} --out {W / 'analysis'}")
else:
    log("trace_analyzer.py not uploaded; skipping analysis")
sh(f"cd {W} && tar -czf {CFG['results']}.tgz merged analysis task_ids_order.json run.log 2>/dev/null; ls -la {W}/*.tgz")
try:
    server.stop()
except Exception:  # noqa: BLE001
    pass
log(f"RUN_DONE in {(time.time() - T0) / 3600:.1f} h")
